#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    const int INF = -1e9;
    int dp[7];
    for (int i = 0; i < 7; ++i) dp[i] = INF;

    for (int i = 0; i < N; ++i) {
        int a[6];
        for (int j = 0; j < 6; ++j) cin >> a[j];

        int opp[7] = {0};
        opp[a[0]] = a[5];
        opp[a[5]] = a[0];
        opp[a[1]] = a[3];
        opp[a[3]] = a[1];
        opp[a[2]] = a[4];
        opp[a[4]] = a[2];

        int side[7];
        for (int b = 1; b <= 6; ++b) {
            int top = opp[b];
            int mx = 0;
            for (int v = 1; v <= 6; ++v) {
                if (v != b && v != top) {
                    mx = max(mx, v);
                }
            }
            side[b] = mx;
        }

        if (i == 0) {
            for (int b = 1; b <= 6; ++b) {
                int top = opp[b];
                dp[top] = max(dp[top], side[b]);
            }
        } else {
            int new_dp[7];
            for (int j = 0; j < 7; ++j) new_dp[j] = INF;

            for (int t_prev = 1; t_prev <= 6; ++t_prev) {
                if (dp[t_prev] == INF) continue;
                int b = t_prev;
                int top_cur = opp[b];
                int val = dp[t_prev] + side[b];
                new_dp[top_cur] = max(new_dp[top_cur], val);
            }

            for (int j = 0; j < 7; ++j) dp[j] = new_dp[j];
        }
    }

    int ans = 0;
    for (int t = 1; t <= 6; ++t) ans = max(ans, dp[t]);

    cout << ans << '\n';
    return 0;
}
